package coverage

import (
	"bufio"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// Profile holds which source lines are covered by tests.
type Profile struct {
	// key: relative file path from module root (e.g. "mutator/expr/foo.go")
	coveredLines map[string]map[int]bool
}

// ParseProfile parses a Go coverage profile (generated by go test -coverprofile)
// using modulePath to strip the module prefix from each entry, leaving relative
// paths that can be matched against absolute file paths.
//
// Example: with modulePath="github.com/acme/app", the profile entry
// "github.com/acme/app/pkg/foo.go:5.1,10.3 2 1" becomes key "pkg/foo.go".
func ParseProfile(path, modulePath string) (*Profile, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	p := &Profile{coveredLines: make(map[string]map[int]bool)}
	prefix := modulePath + "/"
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "mode:") {
			continue
		}
		if err := p.parseLine(line, prefix); err != nil {
			return nil, fmt.Errorf("coverage parse %q: %w", line, err)
		}
	}
	return p, scanner.Err()
}

// IsCovered reports whether the given absolute file path and line number are
// reached by any test. The match uses the relative path suffix of absFile
// against the module-relative keys stored in the profile.
func (p *Profile) IsCovered(absFile string, line int) bool {
	absFile = filepath.ToSlash(absFile)
	for relPath, lines := range p.coveredLines {
		if strings.HasSuffix(absFile, "/"+relPath) || absFile == relPath {
			return lines[line]
		}
	}
	return false
}

// parseLine parses one data line from a coverage profile and strips modulePfx
// from the file name before storing coverage data.
// Format: file:startLine.startCol,endLine.endCol stmtCount hitCount
func (p *Profile) parseLine(line, modulePfx string) error {
	colonIdx := strings.LastIndex(line, ":")
	if colonIdx < 0 {
		return nil
	}
	relFile := relativeCoverageFile(line[:colonIdx], modulePfx)

	fields := strings.Fields(line[colonIdx+1:])
	if len(fields) != 3 {
		return nil
	}

	hitCount, err := strconv.Atoi(fields[2])
	if err != nil {
		return err
	}
	if hitCount == 0 {
		return nil
	}

	startLine, endLine, ok, err := parseCoverageRange(fields[0])
	if err != nil || !ok {
		return err
	}

	p.recordCoveredLines(relFile, startLine, endLine)
	return nil
}

// relativeCoverageFile strips modulePfx from a coverage file path, falling back
// to the raw path when the prefix is absent, and normalises separators.
func relativeCoverageFile(rawFile, modulePfx string) string {
	relFile := strings.TrimPrefix(rawFile, modulePfx)
	if relFile == rawFile {
		// Module prefix not present — use the raw path as-is.
		relFile = rawFile
	}
	return filepath.ToSlash(relFile)
}

// parseCoverageRange parses the "startLine.startCol,endLine.endCol" range field.
// ok is false (with a nil error) when the field is malformed and should be
// skipped rather than treated as an error.
func parseCoverageRange(field string) (startLine, endLine int, ok bool, err error) {
	rangeParts := strings.SplitN(field, ",", 2)
	if len(rangeParts) != 2 {
		return 0, 0, false, nil
	}
	startLine, err = parseLineNum(rangeParts[0])
	if err != nil {
		return 0, 0, false, err
	}
	endLine, err = parseLineNum(rangeParts[1])
	if err != nil {
		return 0, 0, false, err
	}
	return startLine, endLine, true, nil
}

// recordCoveredLines marks lines [startLine, endLine] of relFile as covered.
func (p *Profile) recordCoveredLines(relFile string, startLine, endLine int) {
	if _, ok := p.coveredLines[relFile]; !ok {
		p.coveredLines[relFile] = make(map[int]bool)
	}
	for l := startLine; l <= endLine; l++ {
		p.coveredLines[relFile][l] = true
	}
}

// parseLineNum extracts the line number from "line.col" notation.
func parseLineNum(s string) (int, error) {
	parts := strings.SplitN(s, ".", 2)
	return strconv.Atoi(parts[0])
}

// PerTestProfile maps each (module-relative file path, line) to the sorted list
// of test function names that cover it.  Callers look up by absolute file path
// using CoveringTests; the match is done via suffix so it survives GOPATH/module
// root variations.
type PerTestProfile struct {
	// relPath → line → []testName (sorted)
	data map[string]map[int][]string
}

// CoveringTests returns the sorted test names that cover absFile at lineNum.
// Returns nil when the line is not covered by any individually-run test.
func (p *PerTestProfile) CoveringTests(absFile string, lineNum int) []string {
	if p == nil || lineNum <= 0 {
		return nil
	}
	absSlash := filepath.ToSlash(absFile)
	for relPath, lines := range p.data {
		if strings.HasSuffix(absSlash, "/"+relPath) || absSlash == relPath {
			return lines[lineNum]
		}
	}
	return nil
}

// CountTests returns the number of test functions (Test*, Benchmark*, Fuzz*)
// in pkgPath. Returns 0 on any error or when the package has no tests.
func CountTests(pkgPath string) int {
	names, err := listTestNames(pkgPath)
	if err != nil {
		return 0
	}
	return len(names)
}

// isTestFuncName reports whether name is a top-level test entry point
// (Test*, Benchmark*, or Fuzz*).
func isTestFuncName(name string) bool {
	return strings.HasPrefix(name, "Test") ||
		strings.HasPrefix(name, "Benchmark") ||
		strings.HasPrefix(name, "Fuzz")
}

// listTestNames returns the top-level test function names declared in pkgPath,
// as reported by `go test -list`.
func listTestNames(pkgPath string) ([]string, error) {
	out, err := exec.Command("go", "test", "-list", ".*", pkgPath).Output()
	if err != nil {
		return nil, err
	}
	var names []string
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		line = strings.TrimSpace(line)
		if isTestFuncName(line) {
			names = append(names, line)
		}
	}
	return names, nil
}

// BuildPerTestProfile runs each test function in pkgPath individually with
// -coverprofile to build a map of which lines each test covers.  It uses up
// to workers goroutines in parallel.  Returns nil on any hard failure (the
// caller falls back to the full test suite).
//
// timeout is the per-test run timeout in seconds (same value as --exec-timeout).
// extraTestFlags are appended before the explicit -run flag so that -short, -race,
// etc. are consistent between profile-building and actual mutation test runs.
// perTestJob is a work item for a per-test profiling worker.
type perTestJob struct {
	name string
}

// perTestResult carries the coverage profile produced by one worker.
type perTestResult struct {
	name string
	prof *Profile
}

func BuildPerTestProfile(pkgPath, modulePath, tmpDir string, timeout uint, workers int, extraTestFlags []string) (*PerTestProfile, error) {
	// List test functions (not subtests).
	testNames, err := listTestNames(pkgPath)
	if err != nil {
		return nil, fmt.Errorf("go test -list: %w", err)
	}
	if len(testNames) == 0 {
		return nil, nil
	}

	if workers <= 0 {
		workers = 1
	}

	jobs := make(chan perTestJob, len(testNames))
	results := make(chan perTestResult, len(testNames))

	for i := 0; i < workers; i++ {
		go runPerTestWorker(jobs, results, pkgPath, modulePath, tmpDir, timeout, extraTestFlags)
	}

	for _, name := range testNames {
		jobs <- perTestJob{name: name}
	}
	close(jobs)

	// Merge per-test profiles into a single PerTestProfile.
	p := &PerTestProfile{data: make(map[string]map[int][]string)}

	for i := 0; i < len(testNames); i++ {
		applyPerTestResult(p, <-results)
	}

	// Sort test lists for deterministic -run patterns.
	for _, lines := range p.data {
		for line := range lines {
			sort.Strings(lines[line])
		}
	}

	return p, nil
}

func runPerTestWorker(jobs <-chan perTestJob, results chan<- perTestResult, pkgPath, modulePath, tmpDir string, timeout uint, extraTestFlags []string) {
	for job := range jobs {
		profDir := filepath.Join(tmpDir, "per-test", job.name)
		_ = os.MkdirAll(profDir, 0755)
		profPath := filepath.Join(profDir, "coverage.out")

		args := []string{"test"}
		args = append(args, extraTestFlags...)
		args = append(args,
			"-run", "^"+job.name+"$",
			"-coverprofile="+profPath,
			"-covermode=set",
			"-timeout", fmt.Sprintf("%ds", timeout),
			pkgPath)
		cmd := exec.Command("go", args...)
		cmd.Env = os.Environ()
		_ = cmd.Run() // test failures are expected; we only care about coverage

		prof, err := ParseProfile(profPath, modulePath)
		if err != nil {
			results <- perTestResult{name: job.name, prof: nil}
			continue
		}
		results <- perTestResult{name: job.name, prof: prof}
	}
}

func applyPerTestResult(p *PerTestProfile, r perTestResult) {
	if r.prof == nil {
		return
	}
	for relPath, lines := range r.prof.coveredLines {
		if p.data[relPath] == nil {
			p.data[relPath] = make(map[int][]string)
		}
		for line := range lines {
			p.data[relPath][line] = append(p.data[relPath][line], r.name)
		}
	}
}
